use prusti_contracts::*;

// Verus-style: the "requires" and "ensures" annotations specify the function contract.
// We require min <= max so the clip range is valid.
// The output vector length equals input length, and every element is clipped to the range [min, max].

#[requires(min <= max)]
#[ensures(result.len() == a.len())]
#[ensures(forall(|i: usize| i < a.len() ==> (result[i] >= min && result[i] <= max)))]
fn clip(a: Vec<i8>, min: i8, max: i8) -> Vec<i8> {
    a.into_iter()
        .map(|x| {
            if x < min {
                min
            } else if x > max {
                max
            } else {
                x
            }
        })
        .collect()
}